          content: "亲爱的 ENFP，\n\n你好呀。\n\n我猜你点开这份报告的时候，大概同时开着至少五个浏览器标签页，手机里还有三条未回的消息，脑子里正盘旋着一个新点子、一段昨日的对话，以及对下周末旅行计划的朦胧期待。\n\n你像一个永远在追逐地平线的旅人。别人问你要去哪里，你指了指远方说：“那儿！那儿看起来很有趣！”至于“那儿”到底是哪儿，其实你也不太确定——但确定的是，路上一定会有惊喜。\n\n这份报告不是要给你的好奇心套上缰绳，而是想为你画一张关于你自己的地图。不是为了让你停下来，而是为了让你在奔跑的时候，更清楚自己为何而跑，为何而笑，又为何在某些深夜，突然感到一阵没来由的疲惫。\n\n来吧，让我们看看你这阵风，究竟是由怎样的气流构成的。"
