            N: { value: 88, text: "你脑子里有一台永动的“意义和可能性挖掘机”。别人跟你说“我买了双鞋”，你脑子里已经开始自动生成剧本：这双鞋将带他走向何方？它会见证怎样的故事？它如果会说话，第一句会是什么？至于这双鞋本身是几码的、什么材质，关你屁事，你又不是鞋柜。" },
