            energySource: "低结构性、高自主权、鼓励创新与开放沟通、人际关系真诚透明、任务具有多样性及可见的个人成长空间。",
            energyDrain: "高度官僚化、重复性事务工作、缺乏人际互动的孤立任务、严苛的微观管理及充满政治博弈的组织氛围。",
            survivalTip: "实施“时间区块管理法”为Te功能分配明确、有限的执行窗口。同时，在任务设计中有意识地融入Ne-Fi的激励元素，如将重复性任务与更大的、有意义的个人目标进行叙事连接。"
