            prescription: "去！做！点！人！事！去给朋友的朋友圈点个赞，去楼下便利店跟店员说声谢谢，去撸一撸邻居的狗。你需要一点点真实的、肤浅的、温暖的人际触碰，来提醒你，你他妈还是个人，不是个飘在空中的思想体。"
