            energySource: "让你续命的工作：安静、独立、有明确的目标和意义、同事友善且不聒噪、老板信任你的判断。",
            energyDrain: "让你想死的工作：开放式办公室、永无止境的团队建设活动、工作内容毫无意义、老板是个只看KPI的傻X。",
            survivalTip: "保命技巧：学会给你的Fe穿上“雨衣”。别人的情绪是雨，你可以感受它的存在，但别让它淋湿你的内衣。每天下班后，给自己一段绝对的独处“烘干时间”。"
