            loveReception: "你希望对方怎么爱你：懂你。不是懂你喜欢吃什么，而是懂你为什么笑，为什么沉默，为什么突然想一个人待着。你需要的是灵魂的共振，是那种“我不说，但你都懂”的神交。醒醒，这种人比熊猫还稀有。",
            conflictTrap: "吵架模式：先忍。用Fe维持和谐，内心用Ni-Ti疯狂分析、扣分。忍到临界点，突然“关门”。在对方一脸懵逼中，你已经把他/她从你的精神世界里彻底拉黑，连个缓冲都没有。",
