          swingWarning: "你的J倾向赋予了你强大的执行力和责任感。但请注意，这份“让事情完成”的驱动力，有时会让你忽略过程的风景和你自己的疲惫。你像一个不知疲倦的马拉松领跑员，不断回头鼓励大家跟上，却忘了看看自己的心跳是否已经超速。你的J，需要被你自己的F温柔地照看。"
