            { name: "Ne", role: "深夜里焦虑的未来编剧", desc: "它会让你在脑子里上演一百种你关心的人可能遇到的糟糕事，然后你就焦虑得睡不着，恨不得半夜给人家发信息确认安全。" },
            { name: "Si", role: "你最讨厌的“经验主义”", desc: "你最烦别人说“我们以前都是这么做的”。对你来说，过去是用来超越的，不是用来遵守的。所以你也常常记不住过去的教训。" },
            { name: "Te", role: "黑化后的独裁暴君", desc: "极度崩溃时，你会变成一个冷酷、专横、只看结果的效率狂魔。你会用命令的口吻说话，无视所有人的感受。那是你被逼到墙角的最后挣扎。" }
