            conflictTrap: "吵架时的你：你会立刻启动“关系修复”模式，主动沟通，主动认错（哪怕不是你的错），只求恢复和谐。但你的内心可能在疯狂呐喊：“明明是你的错！我委屈！”然后这些委屈攒着攒着，就变成了某天的一顿大吵。",
            translator: "当你想说“我没事，我们别吵了”（其实内心很有事）时，请试着说：“我现在有点情绪上头，不太能理性沟通。我们都冷静半小时再谈，好吗？这半小时里，我依然爱你/在乎你。”"
