            { name: "Ni", role: "辅助功能 (Parent) · 内倾直觉", rating: 4, voice: "核心运作模式：对未来可能性的收敛性洞察，尤其是在“人”的发展方面。", gift: "为Fe的人际关注提供长远的方向与深度。善于识别他人的潜能，并能构建出一个凝聚人心的未来愿景。这使得ENFJ的关怀具有战略性和成长性。认知盲点：可能因过度执着于自己预见的“最佳未来”，而忽略他人的独立意志或现实中的复杂变量。" },
            { name: "Se", role: "第三功能 (Eternal Child) · 外倾感觉", rating: 3, voice: "核心运作模式：对当下感官体验、美学与具体现实的欣赏与参与。", gift: "在放松状态下，ENFJ会展现出对美好事物、高品质体验和身体享受的热爱。这是其释放压力、与当下现实连接的重要途径。认知盲点：在压力状态下，可能演变为对感官刺激的过度依赖，以逃避更深层的情感或逻辑问题（Fe-Se循环）。" },
            { name: "Ti", role: "劣势功能 (Anima/Animus) · 内倾思考", rating: 1, voice: "核心运作模式：非个人化的、严谨的内在逻辑分析与系统构建。", gift: "ENFJ的成长整合关键。健康发展能为个体的Fe热情提供理性的框架与边界，避免情感泛滥。常态下对脱离人际的纯粹逻辑感到陌生；在压力下可能表现为思维混乱、易被逻辑攻击伤害，或反向表现为冷酷、教条式的逻辑强加。" }
