          swingWarning: "你的J倾向高达90%，这让你的生活像一列按照精确时刻表行驶的高速列车。效率奇高，但容错率很低。当列车遇到意外的轨道故障时，你内心的秩序感会受到巨大冲击。请记得，有时绕一下路，看到的风景或许比原计划更美。"
