            { name: "Ti", role: "第六功能 · 批判家", desc: "你内心的批评者会用一种扭曲的Ti来挑剔一切，包括你自己：“你的模型有漏洞。你的逻辑不严谨。你只是个假装聪明的笨蛋。”它让你陷入无休止的内部逻辑辩论。" },
            { name: "Fe", role: "第七功能 · 盲点", desc: "你对群体氛围、社交礼仪和人际和谐常常不够敏感。你可能会在不经意间说出“实话”，却伤害了别人的感情。你不知道如何安抚一个哭泣的人，你只会递上解决方案。" },
            { name: "Si", role: "第八功能 · 魔鬼", desc: "在极度崩溃时，你可能会被过去的、琐碎的细节所淹没，陷入对回忆的强迫性反刍。你会纠结于过去某个决定的对错，完全丧失了向前看的动力。" }
