            { name: "Fi", role: "随军小牧师 · 被遗忘的灵魂拷问者", rating: 1, voice: "“呃……将军……我们打这场仗……到底是为了谁？”", gift: "这位小牧师平时被关在小黑屋里。只有在夜深人静、或者你遭遇重大挫败时，他才会飘出来，问你一些让你哑口无言的问题。然后你就会陷入短暂的、深刻的空虚和自我怀疑。" }
