          description: "你不仅拥有强大的逻辑分析能力和好奇心，你的Si（内倾感觉）也相当活跃。这意味着你非常依赖一个熟悉、舒适、充满个人印记的物理和心理环境。你需要在固定的时间、固定的地点、用固定的方式来进行思考。你的创造力需要一个稳定的“基地”。"
