          somaticPrescription: "你需要的是能将你从思维世界“解救”出来、但又不需要复杂社交的身体活动。独自一人的散步、游泳、或单纯地躺在黑暗的房间里听白噪音。这些活动能让你的大脑暂时“挂起”，让你的身体感官接管，从而获得深度的休息。"
