            { name: "Te", role: "深夜里焦虑的效率大师", desc: "它会在你玩得正嗨时，突然在你耳边低语：“你还有三个Deadline没完成。你效率太低了。”然后你就焦虑了。" },
            { name: "Fi", role: "你永远找不到的自我", desc: "你能为任何人辩护，但当别人问你“你自己到底想要什么？”时，你会当场死机，然后回答：“呃……你饿不饿？”" },
            { name: "Se", role: "失控时的纵欲狂", desc: "压力爆表时，你会疯狂追求感官刺激。暴饮暴食、冲动消费、危险驾驶……用身体的快感来麻痹精神的痛苦。" }
