            { name: "Se", role: "事后诸葛亮", desc: "它会让你在事情结束后，反复后悔：“我当时要是那么说/那么做就好了！”让你陷入无尽的内耗。" },
            { name: "Ni", role: "你永远看不清的未来", desc: "“你五年后想干什么？”这个问题能让你当场死机。你忙着活好今天，照顾大家，哪有空想那么远。" },
            { name: "Te", role: "黑化后的独裁者", desc: "极度崩溃时，你会变得冷酷无情，用命令的口吻说话，要求所有人必须按规矩办事。那是你最不像自己的一刻。" }
