            conflictTrap: "吵架模式：你会把伴侣当成一个需要被“纠正”的下属。你指出错误，给出整改意见，设定改正期限。然后你满意地觉得自己解决了问题。结果发现伴侣在另一个房间哭。",
            translator: "在你准备“下达指令”之前，请把你的嘴缝上一半。然后说：“我感觉到你现在很生气/难过。跟我说说。”听完之后，说：“我知道了。我需要点时间想想。但我听见你说的了。”"
