          content: "哟，ISFP。\n\n又在发呆呢？还是在等那个“对的时刻”？让我猜猜，你是不是有个才华横溢的爱好，买了全套最专业的装备，然后……它们就在角落里吃灰，因为“我还没找到感觉”。\n\n你是不是觉得这个世界特别糙、特别吵、特别没美感？那些直男审美、996福报、还有各种必须“立刻给出方案”的会议，都让你灵魂出窍。你只想安安静静地，听一首好歌，撸一只猫，或者画一幅只有你自己懂的小画。\n\n恭喜你，你是人间稀有的“人形美颜滤镜”，是“氛围感”这个词的活体解释。但你也因此成了“差不多先生”和“到时候再说小姐”的终身荣誉会员。这份病历不打算治好你的“拖延”和“散漫”——那是你灵感的土壤。它只是想让你在又一次因为“没感觉”而放过自己之后，能有个地方，让你嘿嘿一笑。"
