            { name: "Ne", role: "第六功能 (Critical Parent)", desc: "自我批判来源：以发散的可能性攻击Fi的确定选择，引发对“更好选择”的焦虑与决策犹豫。" },
            { name: "Ti", role: "第七功能 (Trickster)", desc: "认知盲区：对脱离情感与价值的纯粹逻辑体系感到困惑与不耐。" },
            { name: "Si", role: "第八功能 (Demon)", desc: "极端应激表现：在人格结构面临崩溃威胁时，被过去的、带有强烈感官印记的痛苦记忆所淹没。" }
